const cfg = $('Config').first().json;
const pick = (row, names) => {
  const keys = Object.keys(row);
  for (const n of names) {
    const k = keys.find(x => x.trim().toLowerCase() === n);
    if (k !== undefined && row[k] !== undefined && String(row[k]).trim() !== '') return row[k];
  }
  return undefined;
};
const isActive = (v) => v === undefined || ['true', 'yes', '1', 'y'].includes(String(v).trim().toLowerCase());
let prompts = $input.all()
  .map(i => i.json)
  .map(r => ({
    prompt_id: String(pick(r, ['prompt_id', 'id']) !== undefined ? pick(r, ['prompt_id', 'id']) : (r.row_number !== undefined ? r.row_number - 1 : '')),
    prompt: pick(r, ['prompt']),
    prompt_type: String(pick(r, ['prompt_type', 'category', 'type']) || '').trim().toLowerCase(),
    active: pick(r, ['active']),
  }))
  .filter(r => r.prompt && String(r.prompt).trim() !== '' && isActive(r.active))
  .sort((a, b) => String(a.prompt_id).localeCompare(String(b.prompt_id), undefined, { numeric: true }));

const testMode = cfg.test_mode === true || String(cfg.test_mode).toLowerCase() === 'true';
const runs = testMode ? Number(cfg.test_runs_per_prompt || 1) : Number(cfg.full_runs_per_prompt || 5);
const providers = String(testMode ? cfg.test_providers : cfg.full_providers).split(',').map(s => s.trim()).filter(Boolean);
if (testMode && Number(cfg.test_prompt_limit) > 0) prompts = prompts.slice(0, Number(cfg.test_prompt_limit));
if (prompts.length === 0) throw new Error('No active prompts found in the prompts sheet (needs a prompt column).');

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const singleTypes = String(cfg.single_run_prompt_types || '').split(',').map(norm).filter(Boolean);
const singleCount = Number(cfg.single_run_count || 1);
const runsFor = (p) => singleTypes.includes(norm(p.prompt_type)) ? Math.min(singleCount, runs) : runs;
const items = [];
for (let run = 1; run <= runs; run++) {
  for (const p of prompts) {
    if (run > runsFor(p)) continue;
    for (const provider of providers) {
      items.push({ json: {
        run_id: String(cfg.run_id),
        week: cfg.week,
        week_start: cfg.week_start,
        mode: testMode ? 'test' : 'production',
        prompt_id: p.prompt_id,
        prompt: String(p.prompt).trim(),
        prompt_type: p.prompt_type,
        provider: provider,
        run_number: run,
        target_brand: cfg.target_brand,
        brand_aliases: cfg.brand_aliases || '',
      }});
    }
  }
}
return items;

// Pair each answer with its call by position within its AI tool branch
const safeAll = (name, out) => { try { return out === undefined ? $(name).all() : $(name).all(out); } catch (e) { return []; } };
const pairs = [];
const branches = [['Ask ChatGPT (web search)', 0], ['Ask Claude (web search)', 1], ['Ask Perplexity (web search)', 2], ['Ask Gemini (web search)', 3]];
for (const [aiNode, outIdx] of branches) {
  const metas = safeAll('Route by AI Tool', outIdx);
  const answers = safeAll(aiNode);
  const n = Math.min(metas.length, answers.length);
  for (let i = 0; i < n; i++) pairs.push({ meta: metas[i].json, r: answers[i].json || {} });
}

const extract = (r) => {
  let text = '';
  if (r.error) return { status: 'error', error: typeof r.error === 'string' ? r.error : JSON.stringify(r.error), text: '' };
  if (Array.isArray(r.output)) {
    for (const o of r.output) {
      if (o && o.type === 'message' && Array.isArray(o.content)) {
        for (const c of o.content) { if (typeof c.text === 'string') text += c.text; }
      }
    }
  }
  if (Array.isArray(r.content)) {
    for (const b of r.content) { if (b && b.type === 'text') text += b.text || ''; }
  }
  if (r.content && !Array.isArray(r.content) && Array.isArray(r.content.parts)) {
    for (const pt of r.content.parts) { if (pt && typeof pt.text === 'string' && !pt.thought) text += pt.text; }
  }
  if (!text && Array.isArray(r.candidates) && r.candidates[0] && r.candidates[0].content && Array.isArray(r.candidates[0].content.parts)) {
    for (const pt of r.candidates[0].content.parts) { if (pt && typeof pt.text === 'string' && !pt.thought) text += pt.text; }
  }
  if (!text && typeof r.merged_response === 'string') text = r.merged_response;
  if (!text && typeof r.output_text === 'string') text = r.output_text;
  if (!String(text).trim()) return { status: 'error', error: 'Empty answer from AI tool', text: '' };
  return { status: 'ok', error: '', text: String(text) };
};

const isWordChar = ch => /[a-z0-9]/i.test(ch);
const hasWord = (lower, name) => {
  const n = name.toLowerCase();
  let i = lower.indexOf(n);
  while (i !== -1) {
    const before = i === 0 ? '' : lower[i - 1];
    const after = lower[i + n.length] || '';
    if (!(before && isWordChar(before)) && !(after && isWordChar(after))) return true;
    i = lower.indexOf(n, i + 1);
  }
  return false;
};

return pairs.map(({ meta, r }) => {
  const x = extract(r);
  let mentioned = '';
  if (x.status === 'ok') {
    const names = [meta.target_brand].concat(String(meta.brand_aliases || '').split(','))
      .map(s => String(s || '').trim()).filter(Boolean);
    const lower = x.text.toLowerCase();
    mentioned = names.some(nm => hasWord(lower, nm)) ? 'TRUE' : 'FALSE';
  }
  return { json: {
    timestamp: new Date().toISOString(),
    week: meta.week, week_start: meta.week_start, run_id: meta.run_id, mode: meta.mode,
    prompt_id: meta.prompt_id, prompt: meta.prompt, prompt_type: meta.prompt_type,
    provider: meta.provider, run_number: meta.run_number,
    brand_mentioned: mentioned, status: x.status, error: String(x.error).slice(0, 1000),
    answer: x.text.length > 20000 ? x.text.slice(0, 20000) + ' [truncated]' : x.text,
  } };
});

const cfg = $('Config').first().json;
const calls = $('Build Call List').all().map(i => i.json);
const results = $('Check Brand Mention').all().map(i => i.json);
const testMode = cfg.test_mode === true || String(cfg.test_mode).toLowerCase() === 'true';
const providers = String(testMode ? cfg.test_providers : cfg.full_providers).split(',').map(s => s.trim()).filter(Boolean);

// One result per planned call (prompt + provider + run number); missing/failed results count as failed
const byCall = new Map();
for (const r of results) {
  if (!r || r.prompt_id === undefined || !r.provider) continue;
  const k = [r.prompt_id, r.provider, r.run_number].join('|');
  if (!byCall.has(k) || r.status === 'ok') byCall.set(k, r);
}

const prompts = [];
const seenP = new Set();
for (const c of calls) { if (!seenP.has(c.prompt_id)) { seenP.add(c.prompt_id); prompts.push(c); } }

function tally(list) {
  const ok = list.filter(r => r && r.status === 'ok');
  const mentions = ok.filter(r => String(r.brand_mentioned).toUpperCase() === 'TRUE').length;
  return { attempted: list.length, responses: ok.length, mentions, failed: list.length - ok.length, rate: ok.length ? mentions / ok.length : null };
}

// Previous week (latest production week before this one) from the Mention Rates tab
const prevAll = $input.all().map(i => i.json).filter(r => r && r.week && r.mode === 'production' && String(r.week) < String(cfg.week));
let prevMap = new Map();
if (prevAll.length) {
  const lastWeek = prevAll.map(r => String(r.week)).sort().pop();
  const wk = prevAll.filter(r => String(r.week) === lastWeek);
  const lastRun = wk.map(r => String(r.run_id)).sort((a, b) => Number(a) - Number(b)).pop();
  for (const r of wk.filter(r => String(r.run_id) === lastRun)) {
    const resp = Number(r.responses), m = Number(r.mentions);
    prevMap.set(String(r.prompt_id) + '|' + r.provider, resp ? m / resp : null);
  }
}

const pct = v => (v === null || v === undefined ? 'n/a' : Math.round(v * 100) + '%');
const delta = (cur, prev) => {
  if (cur === null || prev === null || prev === undefined) return '';
  const d = Math.round((cur - prev) * 100);
  return ' (' + (d >= 0 ? '+' : '') + d + 'pp)';
};

const rows = [];
const addRow = (p, prov, t) => rows.push({ json: {
  week: cfg.week, week_start: cfg.week_start, run_id: String(cfg.run_id), mode: testMode ? 'test' : 'production',
  prompt_id: p.prompt_id, prompt: p.prompt, prompt_type: p.prompt_type, provider: prov,
  responses: t.responses, mentions: t.mentions, failed: t.failed,
  mention_rate: t.rate === null ? '' : Math.round(t.rate * 1000) / 10,
} });

const FENCE = String.fromCharCode(96).repeat(3);
const padR = (v, n) => { v = String(v); return v.length > n ? v.slice(0, n - 1) + '~' : v + ' '.repeat(n - v.length); };
const padL = (v, n) => { v = String(v); return v.length >= n ? v : ' '.repeat(n - v.length) + v; };
const shortDelta = (cur, prev) => {
  if (cur === null || prev === null || prev === undefined) return '';
  const d = Math.round((cur - prev) * 100);
  return d === 0 ? ' =' : (d > 0 ? ' +' : ' ') + d;
};
const cell = (t, prev) => {
  if (t.rate === null) return t.failed ? 'fail' : '-';
  return pct(t.rate) + shortDelta(t.rate, prev) + (t.failed ? '*' : '');
};
const COLW = 12;
const niceType = t => String(t).split(' ').map(w => ['b2b','ai'].includes(w.toLowerCase()) ? w.toUpperCase() : w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
let anyFailed = false;

const lines = [];
lines.push(':bar_chart: *AI Visibility Report: ' + cfg.target_brand + '*  |  week of ' + cfg.week_start + (testMode ? '  _(TEST RUN)_' : ''));
lines.push('_Mention rate = share of answers that name ' + cfg.target_brand + '. +/- = change vs last week in points._');
lines.push('');
lines.push('*Overall*');
const ov = [];
ov.push(padR('AI tool', 12) + padL('Rate', 6) + padL('Change', 8) + padL('Mentions', 10) + padL('Failed', 8));
ov.push('-'.repeat(44));
for (const prov of providers) {
  const list = calls.filter(c => c.provider === prov).map(c => byCall.get([c.prompt_id, c.provider, c.run_number].join('|')) || { status: 'missing' });
  const t = tally(list);
  addRow({ prompt_id: 'ALL', prompt: 'All prompts', prompt_type: '' }, prov, t);
  const dl = shortDelta(t.rate, prevMap.get('ALL|' + prov)).trim();
  ov.push(padR(prov, 12) + padL(pct(t.rate), 6) + padL(dl ? dl + 'pp' : '', 8) + padL(t.mentions + '/' + t.responses, 10) + padL(t.failed || '', 8));
}
lines.push(FENCE + ov.join('\n') + FENCE);
lines.push('');

// Per prompt, one table per prompt type
const types = [];
for (const p of prompts) { const ty = p.prompt_type || 'Other'; if (!types.includes(ty)) types.push(ty); }
for (const ty of types) {
  const tbl = [];
  tbl.push(padR('#', 4) + padR('Prompt', 34) + providers.map(pr => padL(pr, COLW)).join(''));
  tbl.push('-'.repeat(38 + COLW * providers.length));
  for (const p of prompts.filter(x => (x.prompt_type || 'Other') === ty)) {
    const cells = [];
    for (const prov of providers) {
      const list = calls.filter(c => c.prompt_id === p.prompt_id && c.provider === prov).map(c => byCall.get([c.prompt_id, c.provider, c.run_number].join('|')) || { status: 'missing' });
      const t = tally(list);
      addRow(p, prov, t);
      if (t.failed) anyFailed = true;
      cells.push(padL(cell(t, prevMap.get(String(p.prompt_id) + '|' + prov)), COLW));
    }
    tbl.push(padR(p.prompt_id, 4) + padR(String(p.prompt).replace(/\s+/g, ' '), 33) + ' ' + cells.join(''));
  }
  const runs = calls.filter(c => (c.prompt_type || 'Other') === ty && c.provider === providers[0]);
  const perPrompt = runs.length ? Math.round(runs.length / prompts.filter(x => (x.prompt_type || 'Other') === ty).length) : 0;
  lines.push('*' + niceType(ty) + '*  _(' + perPrompt + ' run' + (perPrompt === 1 ? '' : 's') + ' per prompt per tool)_');
  lines.push(FENCE + tbl.join('\n') + FENCE);
  lines.push('');
}
if (anyFailed) lines.push('_* some calls failed; rate is based on answers received. fail = every call failed. Full prompts and counts are in the Mention Rates tab._');
else lines.push('_Full prompts and counts are in the Mention Rates tab._');

// Markdown version of the same report (real tables, for the .md file)
const mdEsc = v => String(v).replace(/\s+/g, ' ').replace(/[|]/g, '/');
const md = [];
md.push('# AI Visibility Report: ' + cfg.target_brand);
md.push('');
md.push('Week of ' + cfg.week_start + ' (' + cfg.week + ')' + (testMode ? ' - TEST RUN' : ''));
md.push('');
md.push('Mention rate = share of answers that name ' + cfg.target_brand + '. Change = vs last week, in percentage points.');
md.push('');
md.push('## Overall');
md.push('');
md.push('| AI tool | Rate | Change | Mentions | Failed |');
md.push('|---|---:|---:|---:|---:|');
for (const prov of providers) {
  const list = calls.filter(c => c.provider === prov).map(c => byCall.get([c.prompt_id, c.provider, c.run_number].join('|')) || { status: 'missing' });
  const t = tally(list);
  const dl = shortDelta(t.rate, prevMap.get('ALL|' + prov)).trim();
  md.push('| ' + prov + ' | ' + pct(t.rate) + ' | ' + (dl ? dl + 'pp' : '') + ' | ' + t.mentions + '/' + t.responses + ' | ' + (t.failed || '') + ' |');
}
md.push('');
for (const ty of types) {
  const tp = prompts.filter(x => (x.prompt_type || 'Other') === ty);
  const runs = calls.filter(c => (c.prompt_type || 'Other') === ty && c.provider === providers[0]);
  const perPrompt = tp.length ? Math.round(runs.length / tp.length) : 0;
  md.push('## ' + niceType(ty));
  md.push('');
  md.push('_' + perPrompt + ' run' + (perPrompt === 1 ? '' : 's') + ' per prompt per tool_');
  md.push('');
  md.push('| # | Prompt | ' + providers.join(' | ') + ' |');
  md.push('|---|---|' + providers.map(() => '---:').join('|') + '|');
  for (const p of tp) {
    const cells = providers.map(prov => {
      const list = calls.filter(c => c.prompt_id === p.prompt_id && c.provider === prov).map(c => byCall.get([c.prompt_id, c.provider, c.run_number].join('|')) || { status: 'missing' });
      return cell(tally(list), prevMap.get(String(p.prompt_id) + '|' + prov));
    });
    md.push('| ' + p.prompt_id + ' | ' + mdEsc(p.prompt) + ' | ' + cells.join(' | ') + ' |');
  }
  md.push('');
}
md.push(anyFailed ? '_\* some calls failed; rate is based on answers received. fail = every call failed._' : '_All calls returned an answer._');

let text = lines.join('\n');
if (text.length > 39000) text = text.slice(0, 39000) + '\n... (truncated, see the Mention Rates tab)';
rows[0].json.slack_text = text;
rows[0].json.md_text = md.join('\n');
return rows;
